Tentu, ini adalah contoh kode Node.js menggunakan CommonJS (CJS) dan Axios untuk melakukan permintaan POST ke Cloudinary untuk mengunggah video.

Berdasarkan informasi yang Anda berikan, permintaan tersebut adalah:

*   **URL:** `https://api.cloudinary.com/v1_1/ddmffb1fl/video/upload`
*   **Metode:** `POST`
*   **Header:** `Accept: application/json, text/plain, */*`
*   **Respons yang berhasil:** Kode status `200` dengan respons JSON yang berisi detail aset yang diunggah.

Untuk melakukan permintaan ini, Anda perlu menyediakan beberapa informasi penting yang tidak ada dalam cuplikan Anda, seperti:

1.  **`cloud_name`**: Ini adalah `ddmffb1fl` dari URL Anda.
2.  **`api_key`**: Kunci API Cloudinary Anda.
3.  **`api_secret`**: Rahasia API Cloudinary Anda.
4.  **`timestamp`**: Waktu saat ini dalam format Unix epoch.
5.  **`signature`**: Tanda tangan yang dibuat menggunakan `api_secret`, `timestamp`, dan parameter lainnya. Ini sangat penting untuk otentikasi.
6.  **File video yang akan diunggah**: Ini biasanya dikirim sebagai `multipart/form-data`.

Berikut adalah contoh kodenya:

```javascript
// Import modul yang dibutuhkan
const axios = require('axios');
const fs = require('fs');
const crypto = require('crypto'); // Modul crypto untuk membuat signature

// Konfigurasi Cloudinary
const CLOUDINARY_CLOUD_NAME = 'ddmffb1fl'; // Ganti dengan nama cloud Anda jika berbeda
const CLOUDINARY_API_KEY = 'YOUR_CLOUDINARY_API_KEY'; // Ganti dengan API Key Anda
const CLOUDINARY_API_SECRET = 'YOUR_CLOUDINARY_API_SECRET'; // Ganti dengan API Secret Anda

// Path ke file video yang ingin diunggah
const videoFilePath = './path/to/your/video.mp4'; // Ganti dengan path file video Anda

// Fungsi untuk membuat signature Cloudinary
function generateSignature(params) {
    const sortedParams = Object.keys(params).sort();
    let signatureString = '';
    for (const key of sortedParams) {
        signatureString += `${key}=${params[key]}&`;
    }
    signatureString = signatureString.slice(0, -1); // Hapus '&' terakhir
    return crypto.createHmac('sha256', CLOUDINARY_API_SECRET).update(signatureString).digest('hex');
}

// Fungsi utama untuk mengunggah video
async function uploadVideoToCloudinary() {
    const url = `https://api.cloudinary.com/v1_1/${CLOUDINARY_CLOUD_NAME}/video/upload`;

    // Data yang akan dikirimkan ke Cloudinary
    const params = {
        timestamp: Math.floor(Date.now() / 1000),
        api_key: CLOUDINARY_API_KEY,
        // Anda bisa menambahkan parameter lain seperti 'folder', 'public_id', dll.
        // public_id: 'my_custom_public_id'
    };

    // Buat signature berdasarkan parameter
    params.signature = generateSignature(params);

    // Buat objek FormData untuk mengirim file
    const formData = new FormData();
    formData.append('file', fs.createReadStream(videoFilePath));
    // Tambahkan parameter lain ke formData
    for (const key in params) {
        formData.append(key, params[key]);
    }

    try {
        console.log('Memulai unggahan video...');
        const response = await axios.post(url, formData, {
            headers: {
                'Content-Type': 'multipart/form-data',
                // Header lain yang mungkin diperlukan, tapi Accept biasanya sudah cukup
                'Accept': 'application/json, text/plain, */*'
            }
        });

        console.log('Unggahan berhasil!');
        console.log('Data respons:', response.data);
        return response.data;

    } catch (error) {
        console.error('Terjadi kesalahan saat mengunggah video:');
        if (error.response) {
            // The request was made and the server responded with a status code
            // that falls out of the range of 2xx
            console.error('Status:', error.response.status);
            console.error('Data:', error.response.data);
            console.error('Headers:', error.response.headers);
        } else if (error.request) {
            // The request was made but no response was received
            console.error('Request:', error.request);
        } else {
            // Something happened in setting up the request that triggered an Error
            console.error('Error Message:', error.message);
        }
        console.error('Config:', error.config);
        return null;
    }
}

// Panggil fungsi untuk memulai proses unggah
uploadVideoToCloudinary();
```

**Penjelasan Kode:**

1.  **`require('axios')`**: Mengimpor library Axios untuk membuat permintaan HTTP.
2.  **`require('fs')`**: Mengimpor modul File System bawaan Node.js untuk membaca file video.
3.  **`require('crypto')`**: Mengimpor modul `crypto` untuk membuat tanda tangan (signature) yang diperlukan oleh Cloudinary.
4.  **Konfigurasi Cloudinary**:
    *   `CLOUDINARY_CLOUD_NAME`: Nama cloud Anda (misalnya, `ddmffb1fl`).
    *   `CLOUDINARY_API_KEY`: Kunci API Cloudinary Anda.
    *   `CLOUDINARY_API_SECRET`: Rahasia API Cloudinary Anda. **Pastikan untuk mengganti placeholder ini dengan kredensial Anda yang sebenarnya.**
5.  **`videoFilePath`**: Variabel ini harus berisi jalur (path) ke file video yang ingin Anda unggah di sistem file Anda.
6.  **`generateSignature(params)`**: Fungsi ini sangat penting. Cloudinary memerlukan tanda tangan yang dibuat menggunakan rahasia API Anda, stempel waktu (timestamp), dan parameter permintaan lainnya untuk memverifikasi bahwa permintaan tersebut sah. Fungsi ini mengurutkan parameter, membuat string, dan kemudian menggunakan HMAC-SHA256 untuk menghasilkan tanda tangan.
7.  **`uploadVideoToCloudinary()`**:
    *   Menentukan URL endpoint Cloudinary.
    *   Membuat objek `params` yang berisi `timestamp` (waktu saat ini dalam detik epoch) dan `api_key`. Anda dapat menambahkan parameter lain di sini, seperti `public_id` untuk memberikan ID publik yang spesifik pada aset Anda, atau `folder` untuk mengaturnya dalam folder tertentu di Cloudinary.
    *   Memanggil `generateSignature` untuk mendapatkan tanda tangan.
    *   Membuat objek `FormData`. Ini adalah cara standar untuk mengirim file dan data lain dalam permintaan `multipart/form-data`.
        *   `formData.append('file', fs.createReadStream(videoFilePath))`: Ini menambahkan file video yang akan diunggah.
        *   Parameter lain (`timestamp`, `api_key`, `signature`) juga ditambahkan ke `formData`.
    *   Menggunakan `axios.post(url, formData, { headers: ... })` untuk mengirim permintaan POST.
        *   `headers: { 'Content-Type': 'multipart/form-data' }` sangat penting agar server tahu cara memproses data yang dikirim.
    *   Menangani respons (baik berhasil maupun gagal) dan mencetak hasilnya ke konsol.

**Sebelum Menjalankan Kode:**

1.  **Instal Axios:** Jika Anda belum menginstalnya, jalankan perintah ini di terminal Anda di direktori proyek:
    ```bash
    npm install axios form-data
    ```
    *(Catatan: `form-data` diperlukan untuk bekerja dengan `multipart/form-data` di Node.js).*
2.  **Ganti Placeholder:** Pastikan Anda mengganti `YOUR_CLOUDINARY_API_KEY` dan `YOUR_CLOUDINARY_API_SECRET` dengan kredensial Cloudinary Anda yang sebenarnya.
3.  **Perbarui `videoFilePath`:** Ubah `./path/to/your/video.mp4` menjadi jalur yang benar ke file video yang ingin Anda unggah.

Kode ini akan melakukan permintaan POST ke Cloudinary, mengunggah file video Anda, dan mencetak detail aset yang berhasil diunggah atau pesan kesalahan jika terjadi masalah.

```javascript
const axios = require('axios');
const fs = require('fs');
const crypto = require('crypto');
const FormData = require('form-data');

const CLOUDINARY_CLOUD_NAME = 'ddmffb1fl';
const CLOUDINARY_API_KEY = 'YOUR_CLOUDINARY_API_KEY';
const CLOUDINARY_API_SECRET = 'YOUR_CLOUDINARY_API_SECRET';
const videoFilePath = './path/to/your/video.mp4';

function generateSignature(params) {
    const sortedParams = Object.keys(params).sort();
    let signatureString = '';
    for (const key of sortedParams) {
        signatureString += `${key}=${params[key]}&`;
    }
    signatureString = signatureString.slice(0, -1);
    return crypto.createHmac('sha256', CLOUDINARY_API_SECRET).update(signatureString).digest('hex');
}

async function uploadVideoToCloudinary() {
    const url = `https://api.cloudinary.com/v1_1/${CLOUDINARY_CLOUD_NAME}/video/upload`;

    const params = {
        timestamp: Math.floor(Date.now() / 1000),
        api_key: CLOUDINARY_API_KEY,
    };

    params.signature = generateSignature(params);

    const formData = new FormData();
    formData.append('file', fs.createReadStream(videoFilePath));
    for (const key in params) {
        formData.append(key, params[key]);
    }

    try {
        const response = await axios.post(url, formData, {
            headers: {
                'Content-Type': 'multipart/form-data',
                'Accept': 'application/json, text/plain, */*'
            }
        });
        return response.data;
    } catch (error) {
        if (error.response) {
            console.error('Status:', error.response.status);
            console.error('Data:', error.response.data);
        } else if (error.request) {
            console.error('Request:', error.request);
        } else {
            console.error('Error Message:', error.message);
        }
        return null;
    }
}

uploadVideoToCloudinary().then(data => {
    if (data) {
        console.log('Upload successful:', data);
    } else {
        console.log('Upload failed.');
    }
});
```

