```javascript
const axios = require('axios');

const JOB_API_URL = 'https://media.instasaver.io/api/instagram/job';
const GET_JOB_URL_TEMPLATE = 'https://media.instasaver.io/api/instagram/job/';
const INSTAGRAM_POST_URL = 'https://www.instagram.com/p/DbLHcpVjoDy/?img_index=3&igsh=MXdqNTczaDVobGI5aw==';

// Header yang diperlukan untuk membuat job
const jobHeaders = {
    'Accept': 'application/json, text/plain, */*',
    'Content-Type': 'application/json',
    'X-Timestamp': Date.now().toString(), // Gunakan timestamp saat ini
    'X-Signature': '4abd93e85ba9a8f1ef044b7ea0fb2a0057e3b1d340a52a9b185e86c5e68d1655', // Ini mungkin perlu di-generate ulang atau diganti
    'X-Nonce': 'c23dc3a1c349e7e7eb6b311f98695402', // Ini mungkin perlu di-generate ulang atau diganti
    'X-CSRF-Token': 'bb1ede34e73bc009551fbb067dc65b38173213aa958abc4c590bcd844410a61c', // Ini mungkin perlu di-generate ulang atau diganti
};

async function createInstagramJob() {
    try {
        const response = await axios.post(JOB_API_URL, { url: INSTAGRAM_POST_URL }, {
            headers: jobHeaders
        });
        return response.data;
    } catch (error) {
        console.error('Error creating Instagram job:', error.response ? error.response.data : error.message);
        return null;
    }
}

async function getInstagramJobStatus(jobId) {
    if (!jobId) return null;
    try {
        const response = await axios.get(`${GET_JOB_URL_TEMPLATE}${jobId}`, {
            headers: {
                'Accept': 'application/json, text/plain, */*'
            }
        });
        return response.data;
    } catch (error) {
        console.error(`Error getting job status for ${jobId}:`, error.response ? error.response.data : error.message);
        return null;
    }
}

async function processInstagramPost() {
    const jobCreationResult = await createInstagramJob();

    if (!jobCreationResult || !jobCreationResult.success) {
        console.log('Failed to create job.');
        return;
    }

    const jobId = jobCreationResult.data.jobId;
    console.log(`Job created with ID: ${jobId}. Waiting for completion...`);

    // Polling untuk status job (untuk demonstrasi, ini akan memanggil sekali saja)
    // Dalam aplikasi nyata, Anda mungkin ingin menggunakan loop dengan jeda
    // atau mendengarkan WebSocket jika API mendukungnya.
    setTimeout(async () => {
        const jobStatusResult = await getInstagramJobStatus(jobId);
        if (jobStatusResult && jobStatusResult.success) {
            console.log('Job Status:', jobStatusResult.data);
        } else {
            console.log('Failed to get job status.');
        }
    }, 5000); // Tunggu 5 detik sebelum memeriksa status (sesuaikan sesuai kebutuhan)
}

processInstagramPost();
```
